import assert from 'node:assert/strict';
import {performance} from 'node:perf_hooks';
import {pathToFileURL} from 'node:url';
const root=process.argv[2];
const {ComputeEngine}=await import(pathToFileURL(root+'/src/core.ts').href);
const {RSK_ROW_INSERTION}=await import(pathToFileURL('/Users/arno/dev/compute-engine/test/compute-engine/fixtures/rsk-row-insertion.ts').href);
const oracle=(p:number[])=>{ const rows:number[][]=[];for(let v of p){let j=0;while(true){const row=rows[j]??(rows[j]=[]);const k=row.findIndex(x=>x>v);if(k<0){row.push(v);break;}[row[k],v]=[v,row[k]];j++;}}return ['List',...rows.map(r=>['List',...r])];};
const times=[],counts=[];
for(let t=0;t<7;t++){
 const ce=new ComputeEngine();ce.precision='machine';ce.jit='off';
 const f=ce.box(['Function',RSK_ROW_INSERTION,'_raw']);
 const apply=(p:number[])=>ce.function('Apply',[f,ce.box(['List',...p])]).evaluate();
 const p=[4,3,2,1];assert.deepEqual(apply(p).json,oracle(p));
 ce._cacheStats.reset();ce._cacheStats.enabled=true;
 const q=[3,1,2];const start=performance.now();const result=apply(q);times.push(performance.now()-start);
 assert.deepEqual(result.json,oracle(q));counts.push(ce._cacheStats.snapshot().caches.type.missGeneration);
 ce._cacheStats.enabled=false;
}
console.log(JSON.stringify({root,timesMs:times,typeMissGeneration:counts}));
